/* 



Authors notes:

In this method we stay in 2D and we try to find the intersections between circles in the LP-Norm, centered at the voronoi centers. This changes the problem
from finding intersections of 3d shapes, to finding the radius of circles, such that it minimizes the distance to a given sample point.

So the math looks like this, where A and B are two neighboring voronoi sites, and x is our sample position:

minimize the radius R subject to: ||x - intersect(A, B, R)||^2
where intersect(X,Y,R) computes the intersection of two circles in LP-Norm, at the radius R.

To find the intersections we again use alternating projections which is really cheapt to use in this case.

I really thought gradient descent would be the best choice here with finite differences to update our radius R,
but it turns out to get this to go fast in a shader, simply scanning through from our radii lower bound to our radii upper bound
is actually way quicker... Since we don't have to do two projection steps for each iteration.

This method does generalize to 3D, though it'd need some slight adjustments.

I've also made an optimization to fix potential issues when R is close to the lower bound. For LP Norms outside of L2 (euclidean space),
the intersection at the lowest radius bound is often times not a single point, but instead a line. We can approximate this line by
slightly inflating the balls to get two clear intersection points, and then finding the distance to the line spanned by these intersection points.

For 3d variants, one could attempt this optimization but it's probably better to instead just crank up the projection iterations.

To compare this to my previously posted method for L4-Norm voronoi, the L4-Norm method used alternating projections to
find the intersection of the paraboloids centered at our voronoi sites, in RN+1 (so 3d paraboloids for 2d inputs). The RN+1 method is
more stable in the sense that you're not scanning for the proper radius, you're simply finding the nearest intersection of convex functions.
But that method requires computing derivatives of some nasty functions and as the LP-Norm gets higher (even L6), it starts to require a ton of
newton iterations and alternating projection iterations to work well...


Caveats:

This will have some amount of artifacting in an effort to get this performant enough to run on mobile devices. To remove the artifacts, 
simply increase the scanning iterations and alternating projection iterations in the controls! :)

And yes, of course you could just use jump flooding where your your seed points are the pixels where any neighboring pixel is a different voronoi cell.
but where's the fun in that? That's lame! :) 


<3
*/


//----------------------------------
// Controls
//----------------------------------

//animating or not :)
#define ANIMATE

//use the approximated edge center (recommended)
#define approximate_voronoi_edge_center

//number of ball inflation/scanning iterations
#define SCANNING_ITERS 40

//number of alternating projection iterations
#define ALT_PROJ_ITERS 100

//scale of the voronoi
#define SCALE 6.0

//----------------------------------
// End Controls
//----------------------------------


#define d2(a) dot(a,a)

//hash2 shamelessly stolen from IQ <(^.^<)
vec2 hash2( vec2 p )
{
	// texture based white noise
	return textureLod( iChannel0, (p+0.5)/256.0, 0.0 ).xy;
}

//2d to 1d
float rand(vec2 co){
  return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}



//LP Distance calc
float lengthp(vec2 a, float norm){
    float an = pow(abs(a.x), norm) + pow(abs(a.y), norm);
    return pow(an, 1. / norm);
}
//LP Vector Normalize
vec2 lp_normalize(vec2 a, float norm){
    float denom =lengthp(a, norm);
    return a / denom;
}
//Project onto ball in LP norm at a given radius r, centered at c
vec2 project_lp(vec2 p, vec2 c, float r, float norm){
    return c + lp_normalize(p - c, norm) * r;
}






//a method of projecting onto the intersections of closed convex sets (in this case balls in LP)
vec2 alternating_projections_n(vec2 in_p, vec2 c0, vec2 c1, float rad, float norm){
    vec2 x, y = in_p;
    int i = 0;
    while(i < ALT_PROJ_ITERS){
        x = project_lp(y, c0, rad, norm);
        y = project_lp(x, c1, rad, norm);
        if(d2(x - y) < 1e-7) break;
        i++;
    }
    return y;

}

//approximate the region around the midpoint of the voronoi edge
//when the radius == lengthp(c0 - c1) * .5
//for metrics other than L2, there can be many possible intersections
//so it's easiest to just approximate that as a straight line to avoid oversampling :)
vec2 center_approx(vec2 in_p, vec2 c0, vec2 c1, float rad, float norm){
    vec2 mid = (c0 + c1) * .5;
    vec2 p0 = alternating_projections_n(in_p, c0, c1, rad, norm);
    vec2 dir = p0 - mid;
    vec2 p1 = mid - dir;
    vec2 ba = p1 - p0;
    vec2 pa = in_p - p0;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0);

    return (p0 + ba*h);
}


vec2 nearest_point(vec2 x_in, vec2 c0, vec2 c1, float _start_r, float _end_r, float norm){

    float min_d = 1e10;
    vec2 min_p;

    vec2 mid = (c0 + c1) * .5;

    float start_r = _start_r;
    float end_r = _end_r;




    #ifdef approximate_voronoi_edge_center

    //approximate the region around the midpoint of the voronoi edge
    //as being the distance to a straight line bounded by the intersection
    //of the two LP balls,at some small radius that's slightly greater
    //than the minimum possible radius.
    //without this you need more alternating projection iterations to resolve things
    //however when moving into 3d this will need to be removed.

    start_r += .01;    
    min_p = center_approx(x_in, c0, c1, start_r, norm);
    min_d = d2(x_in - min_p);

    #endif



    for(int j = 0; j < SCANNING_ITERS; j++){
        float u = float(j) / float(SCANNING_ITERS - 1);
        //just scan through the radii from the lower bound to the upper bound
        //and pick the best intersection point :)
        float r = mix(start_r, end_r, u);


        //alternating projections will find AN intersection
        //between two convex sets
        //the keyword being AN.

        //this intersection is not gauranteed to be the closest to our starting point
        //meaning we want to test the found intersection
        //and we also want to reflect about the midpoint, which will give us the other
        //intersecting point.


        vec2 p0 = alternating_projections_n(x_in, c0, c1, r, norm);
        //projection distance
        float d0 = d2(x_in - p0);

        //projection reflection distance
        vec2 dir = p0 - mid;
        float d1 = d2(x_in - (mid - dir));


        if(d0 <= min_d){
            min_p = p0;
            min_d = d0;
        }

        if(d1 <= min_d){
            min_p = mid - dir;
            min_d = d1;
        }




    }

    return min_p;

}


//this portion is all based on IQ's Voronoi Edge Shader
//any additions have been commented
vec2 voronoi( in vec2 x, float norm)
{
    vec2 shade_n = floor(x);
    vec2 shade_f = fract(x);

    //----------------------------------
    // first pass: regular voronoi
    //----------------------------------
	vec2 mo, mg, voronoi_center0, voronoi_center1;
    float cell_id = 0.0;
    float md = 100.0;

    for( int j=-1; j<=1; j++ )
    for( int i=-1; i<=1; i++ )
    {
        vec2 g = vec2(float(i),float(j));
		vec2 o = hash2( shade_n + g );
		#ifdef ANIMATE
        o = 0.5 + 0.35*sin( iTime * .1 + 6.2831*o );
        #endif	
        vec2 r = g + o - shade_f;

        //LP distance 
        float d = lengthp(r, norm);

        if( d<md )
        {

            md = d;
            mg = g;
            mo = o;

            //this is purely for shading lmao
            cell_id = rand(shade_n + g);

        }
    }

    //world space voronoi center
    voronoi_center0 = shade_n + mg + mo;


    //----------------------------------
    // second pass: build list of 5 candidate voronoi neighbors
    //---------------------------------

    int indices[6] = int[](-1,-1,-1,-1,-1,-1);
    float dists[6] = float[](1e10,1e10,1e10,1e10,1e10,1e10);

    //build a list of the 5 nearest voronoi centers in L2.
    //this is purely for speed purposes
    for( int k=0; k<25; k++ )
    {
        //skip ourself
        if(k == 12) continue;

        int i = k / 5 - 2;
        int j = k % 5 - 2;



        vec2 g = mg + vec2(float(i),float(j));
		vec2 o = hash2( shade_n + g ); 
		#ifdef ANIMATE
        o = 0.5 + 0.35*sin( iTime * .1 + 6.2831*o );
        #endif	


        vec2 voronoi_center1 = (g + o + shade_n);
        vec2 avg = (voronoi_center0 + voronoi_center1) * .5;

        //get L2 distance to voronoi neighbor (IQ's method) 
        float d = dot(x - avg, normalize(voronoi_center0 - voronoi_center1));


        //create an ordered list of closest neighbors :) 
        for(int l = 0; l <6; l++){
            if(d <= dists[l]){
                for(int ii = 5; ii > l; ii--){
                    dists[ii] = dists[ii - 1];
                    indices[ii] = indices[ii - 1];
                }
                dists[l] = d;
                indices[l] = k;
                break;

            }
        }

    }

    //----------------------------------
    // third pass: distance to borders, using alternating projections (using the 5 candidate neighbors).
    //----------------------------------

    md = 1e10;//10.0;



    for(int k = 0; k < 6; k++)
    {
        int i = indices[k] / 5 - 2;
        int j = indices[k] % 5 - 2;

        vec2 g = mg + vec2(float(i),float(j)); 
		vec2 o = hash2( shade_n + g );
		#ifdef ANIMATE
        o = 0.5 + 0.35*sin( iTime * .1 + 6.2831*o );
        #endif	

        vec2 r = g + o - shade_f;

        vec2 grad = vec2(0.);

        vec2 voronoi_center1 = shade_n + g + o;

        //LP distance to the midpoint, this is the lower bound for the radius of the balls
        float r0 = lengthp(voronoi_center0 - voronoi_center1, norm) * .5;
        //LP maximum distance to either voronoi center. The upper bound for the radius of the balls
        float r1 = max(lengthp(x - voronoi_center0, norm), lengthp(x - voronoi_center1, norm));

        //find the approximate nearest point on the intersection of balls 
        vec2 x_out = nearest_point(x, voronoi_center0, voronoi_center1, r0, r1, norm);
        float dist = length(x_out.xy - x);

        md = min(md, dist);

    }

    return vec2( md, cell_id );
}


//from anastadunbar:  https://www.shadertoy.com/view/lljSRV
float smooth_floor(float x, float c) {
    float a = fract(x);
    float b = floor(x);
    return ((pow(a,c)-pow(1.-a,c))/2.)+b;
}




vec3 jr_palette(float x){
    float picker = clamp(smooth_floor((x + .125) * 3.0, 10.0) / 3.0, 0.0, 1.0);
    vec3 a = vec3(169,51,0) / 255.0;
    vec3 b = vec3(254,141, 1) / 255.0;
    vec3 c = vec3(89, 119, 29) / 255.0;

    float t = picker;
    return t < .5 ? mix(a, b, t / .5) : mix(b,c, (t - .5) / .5);

}


//Visualization also shamelessly stolen from IQ (>^.^)>
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{


    float norm;

    float mouse = iMouse.x / iResolution.x;


    //----------------------------------
    // clicking changes the norm
    //----------------------------------
    if(iMouse.z <= 0.0){
        norm = float(-cos(iTime * .25) * 3.0 + 4.0);
    }else if(mouse < .25){
        norm = 1.0;
    }
    else if(mouse < .5){
        norm = 2.0;
    }
    else if(mouse < .75){
        norm = 4.0;
    }   
    else if(mouse < 1.0)
    {
        norm = 12.0;
    }



    vec2 p = fragCoord/iResolution.xx;
    vec2 grad = vec2(0.);


    vec2 c = voronoi(SCALE*p, norm);

    //----------------------------------
    // visualization
    //----------------------------------    

    vec3 base_col =  jr_palette(c.y);
    vec3 col = base_col;

    float blend = smoothstep(.0,.5, 0.5 + 0.5*sin(150.0*c.x + iTime * 1.));
    col += c.x *blend * vec3(1.0);   

    col =  mix(vec3( 29, 46, 136) / 255.0, col, clamp(blend  * 2.0,0.,1.25));
    col =  mix(base_col, col, .25);
    col = mix(vec3( 8, 13, 45) / 255.0, col, pow(smoothstep( 0.01, 0.0165, c.x ), 1.) );





	fragColor = vec4(col,1.0);
}
